    "drawingSvg": "<svg viewBox=\"0 0 240 145\" class=\"w-full h-full\"><defs><marker id=\"arr-3063\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto-start-reverse\"><path d=\"M 0 1.5 L 8 5 L 0 8.5 z\" fill=\"#000000\"/></marker></defs><rect x=\"10\" y=\"24\" width=\"100\" height=\"90\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.6\"/><circle cx=\"60\" cy=\"69\" r=\"8\" fill=\"none\" stroke=\"#000000\" stroke-width=\"1.2\"/><circle cx=\"60\" cy=\"69\" r=\"18\" fill=\"none\" stroke=\"#000000\" stroke-width=\"1.2\"/><circle cx=\"60\" cy=\"69\" r=\"30\" fill=\"none\" stroke=\"#000000\" stroke-width=\"1.2\"/><circle cx=\"60\" cy=\"69\" r=\"42\" fill=\"none\" stroke=\"#000000\" stroke-width=\"1.2\"/><text x=\"60\" y=\"126\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">|F| only \u2192 blobs</text><rect x=\"130\" y=\"24\" width=\"100\" height=\"90\" rx=\"0\" fill=\"#ffffff\" stroke=\"#000000\" stroke-width=\"1.6\"/><rect x=\"150\" y=\"40\" width=\"60\" height=\"58\" rx=\"0\" fill=\"none\" stroke=\"#000000\" stroke-width=\"2.2\"/><line x1=\"150\" y1=\"40\" x2=\"210\" y2=\"98\" stroke=\"#000000\" stroke-width=\"1.6\"/><line x1=\"210\" y1=\"40\" x2=\"150\" y2=\"98\" stroke=\"#000000\" stroke-width=\"1.6\"/><text x=\"180\" y=\"126\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#000000\">\u2220F only \u2192 edges survive</text><text x=\"120\" y=\"14\" font-size=\"8.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"bold\" text-anchor=\"middle\" fill=\"#000000\">swap them and the picture follows the PHASE</text></svg>",
